<?php
declare(strict_types=1);
$page=max(1,min(100000,(int)($_GET['page']??1)));
$entries=$db->query('SELECT a.*,u.username FROM admin_audit_log a LEFT JOIN admin_users u ON u.id=a.admin_id ORDER BY a.id DESC LIMIT 100 OFFSET '.(($page-1)*100))->fetchAll();
?>
<section class="card"><h2>Verbindliches Änderungsprotokoll</h2><p>Alle Welten · Gespeicherte Änderungen enthalten die Begründung, Vorgangs-ID sowie den Zustand vor und nach der Änderung. Geschenke haben zusätzliche Belege pro Empfänger.</p><div class="table-wrap"><table><thead><tr><th>Zeit (UTC)</th><th>Admin</th><th>Aktion</th><th>Ziel</th><th>Prüfdetails</th></tr></thead><tbody><?php foreach($entries as $entry): ?><tr><td><?= ah($entry['created_at']) ?></td><td><?= ah($entry['username']??'Entfernt') ?></td><td><?= ah($entry['action']) ?></td><td><?= ah($entry['target_type']) ?> #<?= (int)$entry['target_id'] ?></td><td><details><summary>Begründung & Änderungen</summary><pre><?= ah(json_encode(json_decode($entry['details']??'{}',true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details></td></tr><?php endforeach ?></tbody></table></div><div class="pagination"><?php if($page>1): ?><a href="?page=<?= $page-1 ?>">← Zurück</a><?php endif ?><?php if(count($entries)===100): ?><a href="?page=<?= $page+1 ?>">Weiter →</a><?php endif ?></div></section>
